function easingText(kind: "category" | "easing", value: string): string {
  const key = `${kind}.${value}`;
  return Object.hasOwn(easingLabelKeys, key)
    ? editorMessage(easingLabelKeys[key as keyof typeof easingLabelKeys])
    : value;
}

export const easingDisplayName = (value: string): string => easingText("easing", value);
export const easingCategoryName = (value: string): string => easingText("category", value);
